inline const char* sourceName(int id){return id==1?"PS4 Torrent":id==2?"GameTorrent":id==3?"Love Games":"All sources";}
inline std::string listingURL(int source,int page){if(source==1)return page==1?"https://ps4torrent.net/":"https://ps4torrent.net/page/"+std::to_string(page)+"/";if(source==2)return "https://gametorrent.org/category/playstation-4/"+(page==1?std::string():"page/"+std::to_string(page)+"/");return "https://love-games1.net/load/igry_dlja_konsolej/igry_dlja_playstation_4/42"+(page==1?std::string():"-"+std::to_string(page));}
inline std::string elementText(const std::string&html,const std::string&cls,const std::string&name=""){size_t p=0;while((p=html.find('<',p))!=std::string::npos){auto e=html.find('>',p);if(e==std::string::npos)break;auto tag=html.substr(p,e-p+1);if((name.empty()||tag.compare(1,name.size(),name)==0)&&hasClass(tag,cls)){auto end=html.find("</",e+1);return plain(html.substr(e+1,end-e-1));}p=e+1;}return "";}
inline std::string resolveSourceURL(const std::string&u,int source){auto origin=sourceOrigin(source);if(u.compare(0,2,"//")==0)return "https:"+u;if(!u.empty()&&u[0]=='/')return origin+u;if(u.find("://")!=std::string::npos)return u;return origin+"/"+u;}
inline std::vector<Game> parseSourceCards(const std::string&html,int source){if(source<1||source>3)return {};if(source==1)return parseCards(html);std::vector<Game>out;size_t p=0;std::string marker=source==2?"<article":"<div id=\"entryID";
 while((p=html.find(marker,p))!=std::string::npos){auto e=html.find('>',p);if(e==std::string::npos)break;auto tag=html.substr(p,e-p+1);if(source==2&&!hasClass(tag,"shortstory-item")){p=e+1;continue;}auto end=source==2?html.find("</article>",e):html.find(marker,e);if(end==std::string::npos)end=html.size();auto block=html.substr(e+1,end-e-1);Game g;
  auto a=block.find("<a");if(a==std::string::npos){p=end;continue;}auto ae=block.find('>',a);g.url=resolveSourceURL(attr(block.substr(a,ae-a+1),"href"),source);if(sourceForURL(g.url)!=source||(source==2&&g.url.find("/category/playstation-4/")==std::string::npos)){p=end;continue;}
  if(source==2){auto slash=g.url.find_last_of('/');int local=atoi(g.url.c_str()+slash+1);if(local<=0){p=end;continue;}g.id=1000000000+local;g.title=elementText(block,"title");g.year=elementText(block,"year");if(g.year.size()>=4)g.year.resize(4);g.size="Size on page";}
  else{auto entry=attr(tag,"id");int local=entry.size()>7?atoi(entry.c_str()+7):0;if(local<=0){p=end;continue;}g.id=1500000000+local;auto div=block.find("class=\"titl\"");if(div!=std::string::npos){auto begin=block.find('>',div);auto endTitle=block.find("</div>",begin);g.title=plain(block.substr(begin+1,endTitle-begin-1));}if(g.title.empty()||g.url.find("/gde_eshhe_zagruzit_igry/")!=std::string::npos){p=end;continue;}auto size=block.find("Размер:");if(size!=std::string::npos){auto stop=block.find("</p>",size);g.size=plain(block.substr(size+std::string("Размер:").size(),stop-size-std::string("Размер:").size()));}}
  size_t image=0;while((image=block.find("<img",image))!=std::string::npos){auto ie=block.find('>',image);if(ie==std::string::npos)break;auto it=block.substr(image,ie-image+1);auto path=attr(it,"data-src");if(path.empty())path=attr(it,"src");auto full=resolveSourceURL(path,source);if(sourceForURL(full)==source&&full.find(".svg")==std::string::npos){g.image=full;break;}image=ie+1;}
  if(!g.title.empty()&&!g.image.empty())out.push_back(g);p=end;
 }return out;}
inline int sourceLastPage(const std::string&html,int source){if(source!=3)return lastPage(html);int last=1;size_t p=0;while((p=html.find("/42-",p))!=std::string::npos){size_t start=p+4,end=start;while(end<html.size()&&isdigit((unsigned char)html[end]))++end;if(end>start&&(end==html.size()||html[end]!='-')){int value=atoi(html.c_str()+start);if(value>last&&value<=500)last=value;}p=end;}return last;}
inline std::string providerCachePath(const std::string&root,int source){return root+"/catalog-provider-"+std::to_string(source)+".tsv";}
inline std::vector<Game> providerCached(const std::string&root,int source){auto games=loadCatalog(loadQueue(providerCachePath(root,source)));if(games.empty())return {};for(auto&g:games)if(sourceForURL(g.url)!=source)return {};return games;}
inline bool saveProviderCache(const std::string&root,int source,const std::vector<Game>&games,bool stamp=true,time_t now=time(0)){if(games.empty())return false;for(auto&g:games)if(sourceForURL(g.url)!=source)return false;if(!saveQueue(providerCachePath(root,source),serialize(games)))return false;return !stamp||durableReplace(providerCachePath(root,source)+".time",std::to_string((long long)now));}
inline bool providerCacheFresh(const std::string&root,int source,time_t now=time(0)){auto timestamp=strtoll(readFile(providerCachePath(root,source)+".time").c_str(),0,10);return timestamp>0&&now>=timestamp&&now-timestamp<6*60*60&&!providerCached(root,source).empty();}
inline std::string providerCoverPath(const std::string&root,int source){return root+"/covers/provider-"+std::to_string(source);}
inline std::vector<Game> mergedCatalog(const std::string&bundle,const std::string&cache){auto saved=loadCatalog(readFile(cache)),built=loadCatalog(readFile(bundle));auto slash=cache.find_last_of('/');auto root=slash==std::string::npos?std::string("."):cache.substr(0,slash);std::vector<Game>out;for(int source=1;source<=3;source++){auto part=providerCached(root,source);if(part.empty()){for(auto&g:saved)if(sourceForURL(g.url)==source)part.push_back(g);if(part.empty())for(auto&g:built)if(sourceForURL(g.url)==source)part.push_back(g);}out.insert(out.end(),part.begin(),part.end());}return out;}
